// it — Italiano.
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// TOM: **tu**, nunca *Lei*. O italiano tem a mesma escolha que o alemão e o francês, e o Syden a faz
// do mesmo jeito em toda língua — um app de amigos que trata por "Lei" soa como banco.
// Vale também para o imperativo: `scegli`, `scrivi`, `prova`, e não `scelga`, `scriva`, `provi`.
//
// VOCABULÁRIO, decidido uma vez: comunidade = comunità, canal = canale, sala de voz = stanza vocale,
// tópico = discussione, transmissão = trasmissione, lixeira = cestino, selo = sigillo, insígnia =
// distintivo. "Password", "server", "offline", "emoji" e "soundboard" ficam como estão: é como se
// escreve em italiano de verdade, e traduzi-las por invenção deixaria a tela mais estranha.

