  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.': 'Il distintivo compare qui quando cadrà il primo traguardo. Fino ad allora resta da parte — e arrivarci è proprio quello che vorrà dire.',
