  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': 'I traguardi qui sotto sono stati scelti perché non ci sia modo di arrivarci da soli — ognuno ha bisogno di più di una persona, nel tempo.',
