  'Lobisomem': 'Lupo mannaro',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Di notte, scegli con gli altri lupi mannari chi attaccare. Di giorno, non far sospettare nessuno.',
  'Vidente': 'Veggente',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Di notte, scopri se qualcuno è un lupo mannaro. Dillo di giorno, se pensi che valga il rischio.',
  'Anjo': 'Angelo',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Di notte, scegli qualcuno da proteggere. Se i lupi mannari attaccano quella persona, sopravvive.',
  'Da vila': 'Del villaggio',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Di notte, dormi. Di giorno, scopri chi sono i lupi mannari e vota per toglierli dal gioco.',
