  'Noite {n}. A vila dorme.': 'Notte {n}. Il villaggio dorme.',
  'Os lobisomens atacaram {nome} durante a noite.': 'Durante la notte i lupi mannari hanno attaccato {nome}.',
  'Ninguém morreu esta noite.': 'Stanotte nessuna vittima.',
