  'Empate: ninguém sai hoje.': 'Pareggio: oggi non esce nessuno.',
  'Clique em quem os lobisomens vão atacar.': 'Clicca su chi attaccheranno i lupi mannari.',
  'Você já usou a sua visão esta noite.': 'Hai già usato la tua visione stanotte.',
  'Clique em alguém para descobrir se é lobisomem.': 'Clicca su qualcuno per scoprire se è un lupo mannaro.',
  'Clique em quem você quer proteger esta noite.': 'Clicca su chi vuoi proteggere stanotte.',
  'Durma. Os outros papéis estão agindo.': 'Dormi. Gli altri ruoli stanno agendo.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'Sei fuori dal gioco. Ora puoi solo guardare — senza dire niente!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'Clicca su chi vuoi togliere dal gioco. Esce chi ha più voti; in caso di pareggio, nessuno.',
