  'Cargos automáticos': 'Ruoli automatici',
  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'Crea prima i ruoli della comunità, in Membri. Poi torna qui per assegnarli in automatico.',
  'Cargo de quem entra': 'Ruolo di chi entra',
  'Toda pessoa nova recebe estes cargos ao entrar na comunidade.': 'Ogni nuova persona riceve questi ruoli quando entra nella comunità.',
