  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden pubblica nel canale un messaggio con un\'emoji per ogni ruolo. Chi reagisce ottiene il ruolo; chi toglie la reazione lo perde.',
