  'Quais jogos a turma joga, com quantas pessoas e quantas partidas vão até o fim. Só contagem: respostas e desenhos não são guardados. Conta a partir de 12/10/2026.': 'A quali giochi gioca il gruppo, in quante persone e quante partite arrivano alla fine. Solo conteggi: risposte e disegni non vengono salvati. Conteggio dal 12/10/2026.',
