  'O arquivo': 'Il file',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) non è più su Syden perché {quem} ha dichiarato di detenerne i diritti. Se avevi l\'autorizzazione a pubblicare questo contenuto, rispondi qui spiegando: la tua risposta sarà presa in considerazione. Finché la cosa non sarà chiarita, il contenuto resta fuori. I termini spiegano come funziona, nella sezione 4: https://syden.chat/termos.html#direito-autoral',
