  'Monstros de fantasia': 'Mostri fantasy',
  'Sai um monstro secreto, e cada um chuta outros da lista. Cada chute mostra o que bate com o secreto: tipo, tamanho, nível, alinhamento e como ele se desloca. Quem acertar com menos chutes ganha mais pontos.': 'Esce un mostro segreto, e ognuno prova con altri della lista. Ogni tentativo mostra cosa coincide con quello segreto: tipo, taglia, livello, allineamento e come si muove. Chi indovina con meno tentativi guadagna più punti.',
  'Sai uma figura secreta da mitologia, e cada um chuta outras. Cada chute mostra o que bate com a secreta: a mitologia, o tipo, a forma e o que ela governa. Quem acertar com menos chutes ganha mais pontos.': 'Esce una figura segreta della mitologia, e ognuno prova con altre. Ogni tentativo mostra cosa coincide con quella segreta: la mitologia, il tipo, la forma e ciò su cui regna. Chi indovina con meno tentativi guadagna più punti.',
  'Países': 'Paesi',
  'Sai um país secreto, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a sub-região e a população. Quem acertar com menos chutes ganha mais pontos.': 'Esce un paese segreto, e ognuno prova con altri. Ogni tentativo mostra la distanza e la direzione verso quello segreto, la regione, la sottoregione e la popolazione. Chi indovina con meno tentativi guadagna più punti.',
  'Apagar conversa': 'Elimina conversazione',
  'A conversa sai da sua lista e as mensagens somem só para você. As outras pessoas continuam vendo tudo, e uma mensagem nova traz a conversa de volta.': 'La conversazione esce dalla tua lista e i messaggi spariscono solo per te. Le altre persone continuano a vedere tutto, e un nuovo messaggio riporta la conversazione.',
