  'Festa dos coelhos': 'Festa dei conigli',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'Cinque round di giochi rapidi, ognuno sul proprio schermo: riflessi, mira, memoria e occhio. Chi fa meglio in ogni round prende più punti.',
  'Saque rápido': 'Colpo rapido',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'Aspetta il segnale e premi il più in fretta possibile. Prima del segnale, sei fuori.',
  'Medidor de força': 'Misuratore di forza',
  'Pare a barra o mais perto possível de 100%.': 'Ferma la barra il più vicino possibile al 100%.',
