  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'Ferma l\'orologio a 10 secondi esatti. I numeri spariscono dopo il 3.',
  'Jogo dos copos': 'Gioco dei bicchieri',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'Guarda dov\'è la carota e segui il bicchiere. Indovinare prima vale di più.',
  'Siga o coelho': 'Segui il coniglio',
