  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': 'L\'asse si crepa quando qualcuno ci si ferma sopra. Continua a muoverti e spingi gli altri in acqua!',
  'A torre do celeiro': 'La torre del fienile',
