  'A turma caiu.': 'La banda è caduta.',
  'A turma inteira contra a toupeira-rei, que sai das tocas em três fases. Fuja das marcas no chão, pegue os torrões azulados e atire de volta. Ganha a turma, ou ninguém.': 'Tutta la banda contro la talpa regina, che esce dalle tane in tre fasi. Evita i segni sul terreno, raccogli le zolle azzurrine e rilanciale. Vince la banda, o nessuno.',
  'Abóboras ladeira abaixo': 'Zucche in discesa',
  'Acerte os corvos que passarem. No coelhinho, não!': 'Colpisci i corvi che passano. Il coniglietto no!',
