  'Água e sol': 'Acqua e sole',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': 'Alterna ← e → a ritmo. Con troppa fretta, il fiato finisce.',
  'Ao calendário': 'Al calendario',
  'Ao guarda-roupa': 'Al guardaroba',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': 'Premi la freccia che appare per tirare la corda. Se sbagli, ti blocchi!',
  'Aperte para a roda frear. Ela sempre desliza um pouco antes de parar.': 'Premi per frenare la ruota. Scivola sempre un po\' prima di fermarsi.',
  'Aperte sem parar para nadar. Quando vier um tronco, mergulhe!': 'Premi senza sosta per nuotare. Quando arriva un tronco, tuffati!',
