  'Bata nas lagartas que saírem das tocas. No coelhinho, não!': 'Colpisci i bruchi che escono dalle tane. Il coniglietto no!',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': 'Colpisci quando appare il fiore uguale a quello del riquadro. Sulla figura sbagliata, sei fuori.',
