  'Bomba de semente pronta': 'Bomba di semi pronta',
  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': 'Pompa quando l\'anello si accende. Fuori tempo, l\'aria scappa.',
  'Brasas da fogueira': 'Braci del falò',
  'Cabo de guerra': 'Tiro alla fune',
  'Cada um rema de um lado: a remada empurra a balsa para o outro. Juntos, ela vai para a frente. Peguem as cenouras!': 'Ognuno rema da un lato: la remata spinge la zattera verso l\'altro. Insieme, va avanti. Prendete le carote!',
  'Caiu! Agora é torcer de longe.': 'Giù dal cielo! Ora si fa il tifo da lontano.',
  'Canteiro que encolhe': 'Aiuola che si restringe',
