  'Chão que desmorona': 'Pavimento che crolla',
  'Chuva de cenouras': 'Pioggia di carote',
  'Cinco': 'Cinque',
  'Coelhos em teco-tecos sobre a horta, atirando ervilhas e uma cenoura teleguiada de cada vez. Dois acertos dá para aguentar; o terceiro derruba. O último no ar ganha.': 'Conigli su piccoli biplani sopra l\'orto, sparando piselli e una carota teleguidata alla volta. Due colpi si reggono; il terzo abbatte. Vince l\'ultimo in aria.',
  'Colheita em dupla': 'Raccolto in coppia',
  'Coma a torta com a sua dupla, alternando ◀ e ▶. Quem acabar primeiro ganha!': 'Mangia la torta con la tua coppia, alternando ◀ e ▶. Vince chi finisce prima!',
  'Come as folhas': 'Mangia le foglie',
  'Corrida de barquinhos no lago, no riacho e no mangue. A água desliza: tire o pé antes da curva, cuidado com a margem e aproveite a correnteza e as argolas. No Solo, contra o relógio e os fantasmas dos amigos.': 'Gare di barchette sul lago, sul ruscello e nella mangrovia. L\'acqua scivola: molla il gas prima della curva, attenzione alla riva e sfrutta la corrente e gli anelli. In solitario, contro il tempo e i fantasmi degli amici.',
  'Corrida de cavalinho': 'Corsa a cavalluccio',
  'Dano da turma: {n}': 'Danni della banda: {n}',
  'De galho em galho': 'Di ramo in ramo',
  'De que cor é a folha da cenoura?': 'Di che colore è la foglia della carota?',
  'Desça pegando as cenouras. Das pedras, fuja!': 'Scendi prendendo le carote. Scappa dai sassi!',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': 'Scopri chi si nasconde. Una sola possibilità: prima è, più vale.',
  'Destampe os potes': 'Apri i barattoli',
  'Desvie das brasas. São só três corações!': 'Schiva le braci. Hai solo tre cuori!',
  'Dez': 'Dieci',
  'Do que uma planta precisa para crescer?': 'Di cosa ha bisogno una pianta per crescere?',
  'Dois acertos você aguenta; o terceiro derruba. Curva fechada perto da cerca protege por um instante.': 'Due colpi si reggono; il terzo abbatte. Una curva stretta vicino al recinto protegge per un istante.',
  'Duas': 'Due',
  'Duelo de aviõezinhos': 'Duello di aeroplanini',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': 'In coppia: chi sta sul ramo lascia cadere le fragole mature, e chi sta sotto le raccoglie con il cesto.',
  'Em que dia é o aniversário do Syden?': 'In che giorno è il compleanno di Syden?',
  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': 'Spingi gli altri fuori dall\'aiuola. Il bordo che lampeggia sta per cadere!',
  'Encurrale a galinha. Cansada, ela fica lenta.': 'Metti la gallina all\'angolo. Quando è stanca, rallenta.',
  'Escolha a resposta certa antes que o tempo acabe.': 'Scegli la risposta giusta prima che scada il tempo.',
  'Escolher a torre': 'Scegli la torre',
  'Esconda-se onde a lanterna não vai olhar. Quem tem a lanterna procura!': 'Nasconditi dove la lanterna non guarderà. Chi ha la lanterna cerca!',
  'Esconde-esconde na horta': 'Nascondino nell\'orto',
  'Espanta a chuva': 'Scaccia la pioggia',
  'Esta subida já tinha começado quando você abriu: você assiste.': 'Questa scalata era già iniziata quando l\'hai aperta: puoi solo guardare.',
  'Fase {n} de {total}': 'Fase {n} di {total}',
  'Foguete de cenoura': 'Razzo di carota',
  'Frear': 'Frenare',
  'Fuga do rio': 'Fuga sul fiume',
  'Fuja das marcas no chão. Passe por cima de um torrão azulado para pegá-lo e atire de volta na toupeira; a bomba de semente é uma por fase.': 'Evita i segni sul terreno. Passa sopra una zolla azzurrina per prenderla e rilanciala alla talpa; la bomba di semi è una per fase.',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': 'Gira ogni coperchio verso la freccia, in fretta. Il verso sbagliato lo stringe di nuovo.',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': 'Ricorda l\'ordine del ballo. Alla fine, di\' chi ha ballato sulla lampada segnata.',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': 'Ricorda dove va ogni barattolo e rimettili tutti al loro posto.',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': 'Dall\'alto rotolano zucche; chi sale cambia corsia per schivarle!',
  'Lagarta': 'Bruco',
  'Lago da horta': 'Lago dell\'orto',
  'Leite e mel': 'Latte e miele',
  'Lesma': 'Lumaca',
  'Leve a nuvem até o canteiro com sede.': 'Porta la nuvola fino all\'aiuola assetata.',
  'Leve as três tábuas até a ponte. Cuidado com as pedras que afundam!': 'Porta le tre assi fino al ponte. Attenzione ai sassi che affondano!',
  'Mangue': 'Mangrovia',
  'Moletom': 'Felpa',
