  'Ouça, repita a batida no mesmo ritmo e acrescente uma no fim.': 'Ascolta, ripeti il colpo con lo stesso ritmo e aggiungine uno alla fine.',
  'Paiol': 'Granaio',
  'Pare cada faixa com o retrato no lugar, de cima para baixo.': 'Ferma ogni striscia con il ritratto al suo posto, dall\'alto in basso.',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': 'Ferma i tre rulli sulla stessa figura. Ogni tris vale un punto.',
