  'Pegue a galinha': 'Prendi la gallina',
  'Pegue as cenouras no gelo e fuja dos repolhos.': 'Prendi le carote sul ghiaccio e scappa dai cavoli.',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'Prendi una carota dorata e portala al cancello. Ne manca una: spingi chi la sta portando!',
