  'Sem vidas: agora é torcer pela turma.': 'Niente più vite: ora si fa il tifo per la banda.',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Segui gli animaletti di tana in tana. Alla fine, indica dov\'è quello con il palloncino.',
  'Silo': 'Silo',
  'Solte o cipó quando ele estiver na faixa clara.': 'Lascia la liana quando è nella fascia chiara.',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Lascia andare quando la rapa punta verso il campo. Più gira veloce, più va lontano.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'Sali fino alla banderuola. Le cadute e i corvi riportano all\'ultimo piano.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'Scala il fienile su assi, balle di fieno e travi che si muovono fino alla banderuola in cima, schivando gli attrezzi che cadono e i corvi. In solitario, contro il tempo e i fantasmi degli amici.',
