  '{n} voltas': '{n} giri',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'L\'energia è la vita e il turbo: urtare il bordo la consuma, la striscia rosa la ricarica.',
  'A nave explodiu: a energia acabou.': 'La navicella è esplosa: energia finita.',
  'Posição: {posicao} de {total}': 'Posizione: {posicao} su {total}',
  'Escolher a pista': 'Scegli la pista',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Corsa di navicelle-carota su una pista sospesa, molto più veloce del kart. L\'energia è la vita e il turbo: urtare il bordo la consuma, la striscia rosa la ricarica, e uscire dalla pista è cadere. In solitario, contro il tempo e i fantasmi degli amici.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'I kart in un\'arena chiusa, ognuno con tre palloncini. Prendi le casse e usa gli oggetti per far scoppiare i palloncini degli altri: chi resta senza palloncini è fuori, e vince chi resta in gara.',
  'Esquadrilha da toca': 'Squadriglia della tana',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Aeroplanini di carota contro i parassiti dell\'orto: schiva i semi, prendi i rinforzi e abbatti lo spaventapasseri meccanico alla fine. Il gruppo vola le stesse ondate, e la squadriglia somma i punti.',
  'O espantalho caiu!': 'Lo spaventapasseri è caduto!',
  'A praga venceu desta vez.': 'Stavolta hanno vinto i parassiti.',
