  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Otto buche in 3D, con rampe, castello e mulino, tutti giocano la stessa nello stesso momento. Trascina per mirare e dare la forza, poi lascia. Vince chi totalizza meno colpi.',
  'Ver o buraco de cima': 'Vedi la buca dall\'alto',
  'Fora da pista! Mais uma tacada.': 'Fuori pista! Un colpo in più.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Trascina di lato per mirare e verso il basso per la forza, poi lascia. Con la tastiera: le frecce mirano e tenere premuto Spazio dà la forza.',
  'Futebol dos coelhos': 'Calcio dei conigli',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Calcetto visto dall\'alto. Tocca il pallone per condurlo, tieni premuto Spazio per tirare più forte e passa con X. Nella stanza, le squadre si completano con dei robot.',
  'Quantos por time?': 'Quanti per squadra?',
