  'Ninguém para jogar.': 'Nessuno con cui giocare.',
  'Caça às pragas da horta': 'Caccia ai parassiti dell\'orto',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Corvi e cavallette attaccano l\'orto. Mira e clicca per colpirli prima che scappino: le munizioni sono contate, e ogni ondata arriva più veloce. Vince chi fa più punti.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Mira e clicca sui parassiti prima che scappino. Ogni colpo costa una carota.',
