  'Tacadas: {n}': 'Colpi: {n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Tira la pallina indietro e lasciala andare. Con la tastiera: le frecce mirano e tenere premuto Spazio dà la forza.',
  'Na água! Mais uma tacada.': 'In acqua! Un colpo in più.',
