  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Frecce per correre, Spazio per saltare (tieni premuto per andare più in alto).',
  'Nenhum amigo jogou esta fase ainda.': 'Nessun amico ha ancora giocato questo livello.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'Pioggia sull\'orto: tutti ricevono {n} carote.',
  '{nome} achou {n} cenouras escondidas.': '{nome} ha trovato {n} carote nascoste.',
  '{nome} trocou de lugar com {outro}.': '{nome} ha scambiato posto con {outro}.',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'Mancava gente: la partita è finita prima del tempo, senza trofei.',
  'Saiu antes do fim': 'Ha lasciato prima della fine',
  'Jogar o dado': 'Lancia il dado',
  '{nome} comprou a cenoura dourada!': '{nome} ha comprato la carota d\'oro!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Comprare la carota d\'oro per {preco} carote?',
  'Comprar': 'Compra',
  '{nome} chegou à cenoura dourada.': '{nome} ha raggiunto la carota d\'oro.',
  'Quantas rodadas?': 'Quanti turni?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'I conigli difendono l\'orto da volpi, corvi e un tasso. Andate avanti insieme, colpite in combo e proteggetevi a vicenda: da 1 a 4 persone.',
  'Pulo do coelho': 'Salto del coniglio',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Una corsa a piattaforme: correre, saltare e non cadere. In solitaria, contro il tempo e i fantasmi dei tuoi amici; con il gruppo, dal vivo, in un livello o in tutti e tre.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Scambia due ortaggi vicini per metterne insieme tre o più uguali. La pila sale senza sosta: non farle raggiungere la cima. Con il gruppo, catene e combo mandano casse agli altri.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Sei buche di minigolf, tutti giocano la stessa nello stesso momento. Tira la pallina indietro e lasciala andare per tirare. Vince chi fa meno colpi in totale.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'A turno si lancia il dado e si avanza nell\'orto. Raccogli carote per comprare la carota d\'oro, e dopo ogni turno il gruppo gioca a un minigioco. Vince chi ha più carote d\'oro.',
  'Os pódios e as conquistas da turma': 'I podi e i traguardi del gruppo',
  'Visitar o quarto': 'Visita la stanza',
  'Quem visita o seu quarto': 'Chi può visitare la tua stanza',
