  'Seus amigos podem entrar e ver os troféus em destaque.': 'I tuoi amici possono entrare e vedere i trofei in evidenza.',
  'Nem os amigos entram, só quem você marcar aqui.': 'Neanche gli amici entrano, solo chi selezioni qui.',
