  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Gira per le capitali del Brasile, compra città e fai pagare l\'affitto a chi ci si ferma. Con una regione intera puoi costruire edifici. Scambia, partecipa alle aste e non restare senza soldi.',
