  'Batalha naval': 'Battaglia navale',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Il domino di sempre, da 2 a 4 persone (in 4, a coppie). Attacca le tessere alle estremità, e chi chiude per primo prende i punti delle mani degli altri.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Il truco brasiliano, con la carta girata e le briscole, in 2 o a coppie in 4. Chiama truco, rilancia a sei, nove e dodici, o lascia. Vince chi arriva a 12 punti.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'La dama brasiliana: mangiare è obbligatorio, in avanti e all\'indietro, e la dama percorre l\'intera diagonale. La stanza guarda.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Ognuno nasconde la propria flotta e spara nel mare dell\'altro. Colpito, spari di nuovo. Vince chi affonda per primo l\'intera flotta. La stanza guarda.',
