  Bispo: 'Alfiere',
  'Cozinha da toca': 'La cucina della tana',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Prendi gli ingredienti dalle casse, tagliali sul tagliere, cuocili sui fornelli e nel forno senza bruciarli, impiatta e consegna allo sportello. Tutti ricevono gli stessi ordini: vince chi consegna più piatti in 3 minuti.',
