  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Log limitati di Docker, SSH, logind e kernel degli ultimi tre avvii. Possono contenere indirizzi IP.",
  "Atualizar diagnóstico": "Aggiorna diagnostica",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Ancora nessuno snapshot. Verrà raccolto alla prossima apertura della cassaforte.",
  "Coletado em {data}": "Raccolto il {data}",
  "Medido pela {nome}": "Misurato da {nome}",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Gli stessi numeri del pannello del fornitore. Include il disco, che il server non misura da solo.",
  "Ações no servidor": "Azioni sul server",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Lo storico di Hetzner: accendere, spegnere e riavviare, dal pannello o dall’API. Un’interruzione senza azioni qui non è stata comandata per queste vie.",
  "Nenhuma ação registrada.": "Nessuna azione registrata.",
