  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Sfoca, cancella o sostituisce quello che si vede dietro di te. L'immagine della fotocamera non lascia il tuo computer per farlo.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Nativa",
  'Resolução': "Risoluzione",
  'Quadros por segundo': "Fotogrammi al secondo",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Per quando la scelta automatica sbaglia: risoluzione e fotogrammi restano quelli che scegli, dall'inizio alla fine della trasmissione.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Gli effetti di voce e fotocamera fatti sul tuo computer, senza inviare niente a un server.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Commando Carota",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Corri e spara con il gruppo: il lanciacarote mira in otto direzioni, la granata apre la strada e chi libera i coniglietti in gabbia ottiene un potenziamento. Il drago aspetta alla fine: da 1 a 4 persone.",
  'Andar e mirar': "Muoviti e mira",
  'Granada': "Granata",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Il sotterraneo della tana",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Attraversate insieme la tana del re fungo: stanze piene di bestioline, un forziere con la carota che va e torna, pulsanti che ne vogliono due alla volta e la porta chiusa a chiave. Da 1 a 4 persone.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Ring della tana",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Boxe di riflessi contro tre avversari del computer. Leggi l'avviso di ogni colpo, schiva o para e colpisci nel varco. Colpire quando il guantone luccica riempie la stella del colpo forte.",
  'Esquivar': "Schiva",
  'Abaixar e defender': "Abbassati e para",
  'Socar': "Colpisci",
  'Soco forte': "Colpo forte",
  'Aperte os socos para levantar!': "Premi i colpi per rialzarti!",
  'Lutas vencidas: {n}': "Incontri vinti: {n}",
  'Nocaute!': "KO!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Rotta Stellare",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Conigli su astronavi sopra la superficie di un pianeta e nello spazio: spara, tieni premuto il colpo per agganciare il bersaglio, ruota su te stesso per deviare i colpi e scegli la strada al bivio. Il gruppo vola sulla stessa rotta, e il boss aspetta alla fine.",
  'Pirueta': "Avvitamento",
  'Segure para travar a mira': "Tieni premuto per agganciare",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Flipper dell’orto",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Un tavolo da flipper nell’orto: tieni la molla, rimbalza sui cavoli e abbatti le tre carote per accendere la tana del coniglio, che libera un’altra pallina. Tre palline, e scuotere troppo blocca il tavolo.",
  'Palhetas': "Alette",
