  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "Un breve GDR a turni: ognuno controlla un eroe del gruppo. Scegliete insieme, combinate gli attacchi e sconfiggete il drago del castello.",
