  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "Esplora i campi, fai amicizia con le bestiole dell'erba alta con una carota e forma una squadra fino a sei. Supera la sfida della casa blu e, nella stanza, combatti contro la squadra di un amico.",
