  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Muoviti col dado e compra la capitale dove ti fermi. Chi si ferma nella città di un altro paga l'affitto.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Ogni riga, colonna e blocco 3 × 3 contiene i numeri da 1 a 9, senza ripetizioni.",
