  "Campeonato": "Campionato",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Con 11 punti, la coppia vede le carte e decide se giocare la mano di undici. Vince chi arriva a 12.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Con la regione intera, costruisci fino a 4 edifici: l'affitto sale con ognuno.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Con le stelle, il colpo forte (★) le consuma tutte in una volta e fa più male.",
