  "Saara": "Sahara",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Esce un animale segreto, e ognuno ne prova altri. Ogni tentativo mostra cosa coincide con quello segreto: la classe, la dieta, dove vive e il peso. Chi indovina con meno tentativi fa più punti.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Esce un dinosauro segreto, e ognuno ne prova altri. Ogni tentativo mostra cosa coincide con quello segreto: il periodo, la dieta, il gruppo, la lunghezza e dove è stato trovato. Chi indovina con meno tentativi fa più punti.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Esce un elemento chimico segreto, e ognuno ne prova altri. Ogni tentativo mostra cosa coincide con quello segreto: la famiglia, lo stato fisico, il periodo, il gruppo e il numero atomico. Chi indovina con meno tentativi fa più punti.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Esce uno stato segreto del Brasile, e ognuno ne prova altri. Ogni tentativo mostra la distanza e la direzione verso quello segreto, la regione, la popolazione, la superficie, la costa e il confine con un altro paese. Chi indovina con meno tentativi fa più punti.",
